{
  "findings": [
    {
      "check_id": "CKV_AZURE_229",
      "title": "Azure SQL Database is not zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database uses the S0 tier and does not enable zone redundancy, leaving it more susceptible to a single availability-zone failure. The SKU must be upgraded to a supported Premium tier before zone redundancy can be enabled."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"P1\"\n  zone_redundant = true\n  tags           = var.common_tags\n}\n",
  "fix_summary": "Upgraded the database from S0 to the zone-redundancy-capable P1 tier and enabled zone redundancy. Ledger was not enabled because the file does not indicate a requirement for cryptographic proof or nonrepudiation, and enabling it is workload-specific."
}
